// Event detail/discovery UI shared by the web routes. Server RLS remains authoritative.
export function eventDetails(e,s,esc,stamp){const mine=e.created_by===s.user.id,a=s.attendance.find(a=>a.event_id===e.id&&a.user_id===s.user.id);return `<article class="card event-detail"><span class="badge">${esc(e.visibility==='public'?'Public event':'Private event')}</span><h2>${esc(e.title)}</h2><p>${esc(e.summary)}</p><p class="preserve-lines">${esc(e.description!==e.summary?e.description:'')}</p><div class="grid"><div><strong>${esc(e.venue)}</strong><p>${esc(e.address)}</p><a href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(e.venue+' '+e.address)}" target="_blank" rel="noopener noreferrer">Open location ↗</a></div><div><strong>${stamp(e.starts_at_millis)}</strong><p>Until ${stamp(e.ends_at_millis)}</p><span class="badge">${Date.now()>=e.starts_at_millis&&Date.now()<=e.ends_at_millis?'Live now':Date.now()>e.ends_at_millis?'Ended':'Upcoming'}</span></div></div><p class="muted">Hosted by ${esc(e.organizer_name)} · ${esc(e.category)} · ${Number(e.attendee_count)||0} going</p>${e.is_cancelled?'<p class="error">This event is cancelled.</p>':`<p>Your status: ${esc(a?.status||'Not selected')}</p><div class="row">${['interested','going','here'].map(v=>`<button class="${a?.status===v?'':'quiet'}" data-action="attendance" data-status="${v}">${v==='here'?"I'm here · self check-in":v==='going'?"I'm going":'Interested'}</button>`).join('')}</div>`}<p class="muted">Check-in is optional for photos. Manual check-in is not location-verified.</p><div class="row"><button data-tab="photos">View / upload photos</button><button data-tab="expenses">Shared expenses</button><button class="quiet" data-action="share-event">Share event link</button><button class="quiet" data-action="calendar-export">Add to calendar</button><button class="quiet" data-action="report-event">Report</button>${mine?'<button class="quiet" data-action="join-link">Create guest join link</button><button class="quiet" data-action="revoke-link">Revoke guest link</button><button class="quiet" data-action="edit-event">Edit event</button>':''}</div>${mine||e.visibility==='public'?`<details><summary>Invite a friend</summary><form id="event-invite-form"><label>Accepted friend<select name="user" required>${s.directory.filter(p=>p.id!==s.user.id&&s.friends.some(f=>f.status==='accepted'&&[f.requester_id,f.addressee_id].includes(p.id))&&!s.invitations.some(i=>i.event_id===e.id&&i.invitee_id===p.id)).map(p=>`<option value="${p.id}">${esc(p.display_name)}</option>`).join('')}</select></label><button type="submit">Send event invitation</button></form></details>`:''}</article>`;}
export function eventCards(events,s,esc,stamp){return `<h3>Explore events / trips</h3><div class="grid">${events.map(e=>`<article class="card event-card"><span class="badge">${esc(e.category)} · ${esc(e.visibility)}</span><h3>${esc(e.title)}</h3><p>${esc(e.summary)}</p><small>${stamp(e.starts_at_millis)} · ${esc(e.venue)}</small><button class="wide quiet" data-action="open-event" data-id="${e.id}">Open event</button></article>`).join('')}</div>`;}
export function incomingInvitations(s,esc){return s.invitations.filter(i=>i.invitee_id===s.user.id&&i.status==='pending').map(i=>`<div class="card"><span class="badge">Event invitation</span><h3>${esc(i.event_title)}</h3><div class="row"><button data-action="accept-event" data-id="${i.id}">Accept & open event</button><button class="quiet" data-action="decline-event" data-id="${i.id}">Decline</button></div></div>`).join('');}
export function editEventForm(e,esc){const local=ms=>{const d=new Date(ms);return new Date(ms-d.getTimezoneOffset()*60000).toISOString().slice(0,16);};return `<h2>Edit event</h2><form id="edit-event-form"><label>Name<input name="title" maxlength="80" required value="${esc(e.title)}"></label><label>Summary<textarea name="summary" required maxlength="300">${esc(e.summary)}</textarea></label><label>Description<textarea name="description" required maxlength="3000">${esc(e.description)}</textarea></label><label>Start<input type="datetime-local" name="start" required value="${local(e.starts_at_millis)}"></label><label>End<input type="datetime-local" name="end" required value="${local(e.ends_at_millis)}"></label><label>Venue<input name="venue" required value="${esc(e.venue)}"></label><label>Address<input name="address" required value="${esc(e.address)}"></label><label>Visibility<select name="visibility">${['public','circle','invite_only'].map(v=>`<option ${e.visibility===v?'selected':''}>${v}</option>`).join('')}</select></label><label class="check"><input name="cancelled" type="checkbox" ${e.is_cancelled?'checked':''}>Cancel this event</label><p class="muted">Changing to public exposes event details and moments to everyone. Expenses remain group-private.</p><button type="submit">Save event changes</button></form>`;}
export function calendarEvents(events,esc,stamp){const days=new Map();for(const e of events){const day=new Date(e.starts_at_millis).toLocaleDateString('en-CA');if(!days.has(day))days.set(day,[]);days.get(day).push(e);}return `<h2>Your event calendar</h2><p class="muted">Tap an event to open details, photos and expenses.</p>${[...days].sort(([a],[b])=>a.localeCompare(b)).map(([day,events])=>`<details class="card"><summary><strong>${esc(day)}</strong> · ${events.length} events</summary>${events.map(e=>`<p>${stamp(e.starts_at_millis)}<br><button class="quiet" data-action="open-event" data-id="${e.id}">${esc(e.title)}</button></p>`).join('')}</details>`).join('')}`;}
export function calendarFile(e){const utc=ms=>new Date(ms).toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');const escape=v=>String(v||'').replace(/\\/g,'\\\\').replace(/\r?\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');const fold=line=>{let parts=[],piece='';for(const c of line){if(new TextEncoder().encode(piece+c).length>70){parts.push(piece);piece=' '+c;}else piece+=c;}parts.push(piece);return parts.join('\r\n');};return ['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Poi//Events//EN','BEGIN:VEVENT',`UID:${e.id}@poi`,`DTSTAMP:${utc(Date.now())}`,`DTSTART:${utc(e.starts_at_millis)}`,`DTEND:${utc(e.ends_at_millis)}`,`SUMMARY:${escape(e.title)}`,`LOCATION:${escape(e.venue+', '+e.address)}`,`DESCRIPTION:${escape(e.description)}`,'END:VEVENT','END:VCALENDAR'].map(fold).join('\r\n')+'\r\n';}
